import './app-craps-table.js';
import { prepareDecimatorReplay } from '../craps/decimator-replay.js';
import { decimatorTableOptions } from '../craps/decimator-table.js';

/** Load Decimator data into the existing craps resolver, with its own scoring skin. */
export function mountDecimatorBattle(snapshot, { names = new Map(), onResults = () => {}, onClose = () => {},
  prepareReplay = prepareDecimatorReplay, ...controls } = {}) {
  if (!document.querySelector('link[data-decimator-craps]')) {
    const link = document.createElement('link'); link.rel = 'stylesheet';
    link.href = '/app/styles/craps-table.css?v=decimator-skin-20261006';
    link.dataset.decimatorCraps = ''; document.head.append(link);
  }
  const element = document.createElement('div'); element.className = 'decimator-craps-host';
  const status = document.createElement('p'); status.setAttribute('role', 'status');
  status.textContent = 'Preparing the Decimator craps battle…';
  const table = document.createElement('app-craps-table');
  element.append(status, table);
  const abort = new AbortController(); let disposed = false;
  prepareReplay(snapshot, { signal: abort.signal }).then(replay => {
    if (disposed) return;
    status.hidden = true;
    table.open(decimatorTableOptions(snapshot, replay, { names, ...controls,
      onResolutionAcknowledged: onResults, onClose,
    }));
  }).catch(error => {
    if (disposed) return;
    status.textContent = error.message;
    const results = document.createElement('button'); results.type = 'button'; results.textContent = 'VIEW RECORDED RESULTS';
    results.onclick = () => onResults({ fallback: true }); element.append(results);
  });
  return { element, table, destroy() { disposed = true; abort.abort(); table.remove(); } };
}
